function activePromos(){const now=Date.now();return promos.filter(r=>r.is_active&&(!r.starts_at||Date.parse(r.starts_at)<=now)&&(!r.ends_at||Date.parse(r.ends_at)>now)&&Number(r.discount_percent)>0&&Number(r.discount_percent)<=100&&Number.isInteger(Number(r.required_quantity))&&Number(r.required_quantity)>=2);}
function eligible(r,v){return v.in_stock&&price(v)===Number(v.price)&&(r.promotion_products||[]).some(x=>x.variant_id===v.id);}
function totals(){let subtotal=0,count=0,discount=0;const remaining=new Map();for(const [id,{v,qty}] of cart){subtotal+=Math.round(price(v)*100)*qty;count+=qty;remaining.set(id,qty);}const applied=[];for(const r of activePromos().sort((a,b)=>Number(b.discount_percent)-Number(a.discount_percent)||a.id.localeCompare(b.id))){const groups=new Map();for(const [id,{v}] of cart){if(!eligible(r,v))continue;const cents=Math.round(price(v)*100);if(!groups.has(cents))groups.set(cents,[]);groups.get(cents).push(id);}let saved=0;for(const [cents,ids] of groups){const n=Number(r.required_quantity);const sets=Math.floor(ids.reduce((sum,id)=>sum+remaining.get(id),0)/n);let used=sets*n;for(const id of ids){const take=Math.min(used,remaining.get(id));remaining.set(id,remaining.get(id)-take);used-=take;}saved+=sets*Math.round(cents*Number(r.discount_percent)/100);}if(saved){discount+=saved;applied.push({name:r.name,discount:saved});}}return {subtotal,discount,count,total:subtotal-discount,applied};}
